import type { Brackets, Subdivision, WealthTax } from '../../../types'
import { I, rate } from '../../helpers'

/**
 * Cantonal + communal income and wealth tax for 2025 in each canton's main city (single, no church tax).
 * Generated by sampling the official ESTV tax calculator (swisstaxcalculator.estv.admin.ch) and converting
 * the tax curves into marginal-rate brackets. Income brackets apply to cantonal taxable income; wealth
 * brackets apply to gross net wealth (cantonal allowances are built in).
 */

const FEDERAL_TOP = 0.115

function canton(code: string, name: string, lat: number, lng: number, city: string, rent1: number, rent3: number, col: number, income: Brackets, wealth: Brackets, extra: Partial<Subdivision> = {}): Subdivision {
  const w: WealthTax = { name: `Cantonal & communal wealth tax (${city})`, brackets: wealth }
  const rates = wealth.map(([, r]) => r).filter((r) => r > 0)
  return {
    code, name, lat, lng,
    cities: [{ name: city, rent1, rent3, col, local: [{ name: `Cantonal & communal tax (${city})`, base: 'ordinary', allowance: 4000, brackets: income }], wealth: w }],
    regionalTopRate: income[income.length - 1][1],
    headline: {
      topIncome: rate(FEDERAL_TOP + income[income.length - 1][1]),
      wealth: `${(Math.min(...rates) * 100).toFixed(2)}% – ${(Math.max(...rates) * 100).toFixed(2)}% (${city})`,
    },
    ...extra,
  }
}

